interface Payable {
    double calculerPaiement();
}

interface Imprimable {
    void imprimer();
}

class Facture implements Payable, Imprimable {
    double montant;
    Facture(double montant) { this.montant = montant; }

    @Override
    public double calculerPaiement() { return montant * 1.2; } // TVA 20%

    @Override
    public void imprimer() {
        System.out.println("Facture : " + calculerPaiement() + " €");
    }
}
